from typing import List, Dict, Any
from document_client import DocumentClient
from document_models import DocumentPayload, TableExtractionResult, Table, TableCell

def extract_tables(payload: DocumentPayload, config: Dict[str, Any] = None) -> TableExtractionResult:
    config = config or {}
    client = DocumentClient(config).get_textract_client()

    response = client.analyze_document(
        Document={"Bytes": payload.document_bytes},
        FeatureTypes=["TABLES"]
    )

    tables: List[Table] = []
    blocks_by_id = {block["Id"]: block for block in response.get("Blocks", [])}

    for block in response.get("Blocks", []):
        if block["BlockType"] == "TABLE":
            table_cells: List[List[TableCell]] = []
            # Initialize rows based on max row index found in cells
            max_row_index = 0
            for relationship in block.get("Relationships", []):
                if relationship["Type"] == "CHILD":
                    for child_id in relationship["Ids"]:
                        cell_block = blocks_by_id.get(child_id)
                        if cell_block and cell_block["BlockType"] == "CELL":
                            r_index = cell_block["RowIndex"]
                            if r_index > max_row_index:
                                max_row_index = r_index

            for _ in range(max_row_index):
                table_cells.append([])

            for relationship in block.get("Relationships", []):
                if relationship["Type"] == "CHILD":
                    for child_id in relationship["Ids"]:
                        cell_block = blocks_by_id.get(child_id)
                        if cell_block and cell_block["BlockType"] == "CELL":
                            cell_content = ""
                            for cell_rel in cell_block.get("Relationships", []):
                                if cell_rel["Type"] == "CHILD":
                                    for word_id in cell_rel["Ids"]:
                                        word_block = blocks_by_id.get(word_id)
                                        if word_block and word_block["BlockType"] == "WORD":
                                            cell_content += word_block.get("Text", "") + " "
                            cell_content = cell_content.strip()

                            row_idx = cell_block["RowIndex"] - 1 # 0-indexed
                            col_idx = cell_block["ColumnIndex"] - 1 # 0-indexed

                            # Ensure row exists
                            while len(table_cells) <= row_idx:
                                table_cells.append([])
                            # Ensure column exists for the row
                            while len(table_cells[row_idx]) <= col_idx:
                                table_cells[row_idx].append(None) # Placeholder

                            table_cells[row_idx][col_idx] = TableCell(
                                row_index=row_idx,
                                column_index=col_idx,
                                content=cell_content,
                                geometry=cell_block.get("Geometry", {})
                            )

            # Replace None placeholders with empty TableCell objects if needed, or filter them out
            # For simplicity, let's ensure all cells are present with empty strings if no content was found.
            # This can be refined based on exact rendering needs.
            final_rows = []
            for row in table_cells:
                current_row = []
                for cell_obj in row:
                    if cell_obj is None:
                        # Create a dummy cell if no content was found for this position
                        current_row.append(TableCell(row_index=0, column_index=0, content="", geometry={})) 
                    else:
                        current_row.append(cell_obj)
                final_rows.append(current_row)

            tables.append(Table(rows=final_rows, geometry=block.get("Geometry", {})))

    return TableExtractionResult(tables=tables)

import boto3
from typing import List, Dict, Any
from document_client import DocumentClient
from document_models import DocumentPayload, KeyValueExtractionResult, KeyValue

def extract_key_values(payload: DocumentPayload, config: Dict[str, Any] = None) -> KeyValueExtractionResult:
    config = config or {}
    client = DocumentClient(config).get_textract_client()

    response = client.analyze_document(
        Document={"Bytes": payload.document_bytes},
        FeatureTypes=["FORMS"]
    )

    key_values: List[KeyValue] = []
    blocks_by_id = {block["Id"]: block for block in response.get("Blocks", [])}

    for block in response.get("Blocks", []):
        if block["BlockType"] == "KEY_VALUE_SET" and "KEY" in block["EntityTypes"]:
            key_text = ""
            value_text = ""
            key_geometry = {}
            value_geometry = {}

            # Extract key text and geometry
            for relationship in block.get("Relationships", []):
                if relationship["Type"] == "CHILD":
                    for child_id in relationship["Ids"]:
                        child_block = blocks_by_id.get(child_id)
                        if child_block and child_block["BlockType"] == "WORD":
                            key_text += child_block.get("Text", "") + " "
            key_text = key_text.strip()
            key_geometry = block.get("Geometry", {})

            # Extract value text and geometry
            for relationship in block.get("Relationships", []):
                if relationship["Type"] == "VALUE":
                    for value_id in relationship["Ids"]:
                        value_block = blocks_by_id.get(value_id)
                        if value_block and "VALUE" in value_block["EntityTypes"]:
                            value_geometry = value_block.get("Geometry", {})
                            for value_rel in value_block.get("Relationships", []):
                                if value_rel["Type"] == "CHILD":
                                    for word_id in value_rel["Ids"]:
                                        word_block = blocks_by_id.get(word_id)
                                        if word_block and word_block["BlockType"] == "WORD":
                                            value_text += word_block.get("Text", "") + " "
                            value_text = value_text.strip()

            if key_text or value_text:
                key_values.append(KeyValue(
                    key=key_text,
                    value=value_text,
                    key_geometry=key_geometry,
                    value_geometry=value_geometry
                ))

    return KeyValueExtractionResult(key_values=key_values)

import os
from typing import Dict, Any
from google.cloud import translate_v3 as translate
from document_client import DocumentClient
from document_models import TranslationResult

def ocr_translate(text: str, target_language: str, source_language: str = None, config: Dict[str, Any] = None) -> TranslationResult:
    config = config or {}
    client = DocumentClient(config).get_translation_client()
    project_id = config.get("gcp_project_id", os.environ.get("GCP_PROJECT_ID"))

    if not project_id:
        raise ValueError("GCP_PROJECT_ID not found in config or environment variables.")

    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language,
            "source_language_code": source_language if source_language else None,
        }
    )

    translated_text = ""
    detected_source_language = source_language

    for translation in response.translations:
        translated_text += translation.translated_text
        if not detected_source_language and translation.detected_language_code:
            detected_source_language = translation.detected_language_code

    return TranslationResult(
        translated_text=translated_text,
        target_language=target_language,
        source_language=detected_source_language
    )
